mapper.select:
SELECT COUNT(*)
FROM audience
WHERE user_id = #{userId}

SELECT COUNT(*)
FROM audience
WHERE user_id = #{userId}
  AND certificate_no_hash = #{certificateNoHash}

SELECT COUNT(*)
FROM audience
WHERE user_id = #{userId}
  AND audience_id != #{audienceId}
  AND certificate_no_hash = #{certificateNoHash}

mapper.delete:
DELETE FROM audience
WHERE user_id = #{userId}
  AND audience_id = #{audienceId}

mapper.update:
UPDATE audience
SET is_default = 1,
    update_time = NOW()
WHERE user_id = #{userId}
  AND audience_id = #{audienceId}
